(() => {
'use strict';const c=window.HVT,$=s=>document.querySelector(s),form=$('#episodeForm');let resource=null,rows=[],live=[],current=null,preview=false,busy=false,dirty=false,sequence=0;
const status=(text,error=false)=>{$('#episodeStatus').textContent=text;$('#episodeStatus').classList.toggle('error',error)};
const rpc=async(name,body)=>{const result=await c.api('/rest/v1/rpc/'+name,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});return Array.isArray(result)?result[0]:result};
function controls(){form.querySelector('fieldset').disabled=busy;$('#episodeSave').disabled=$('#episodePublish').disabled=busy||preview||!resource;$('#episodeNew').disabled=$('#episodeReload').disabled=busy;$('#episodeCoverFields').hidden=form.elements.inherit_cover.checked}
const canLeave=()=>!dirty||window.confirm('Tập đang soạn có thay đổi chưa lưu. Rời bản này?');
function render(){$('#episodeList').innerHTML=rows.length?rows.map(r=>'<div class="section-row"><div><strong>'+c.esc(window.HVTVideoSeries.title(r))+'</strong><small>Thứ tự '+r.episode_order+' · '+(live.some(p=>p.id===r.id)?'Đã công khai':'Bản nháp')+'</small></div><div><button type="button" class="text-link" data-episode-edit="'+r.id+'">Sửa / viết tiếp</button>'+(live.some(p=>p.id===r.id)?'<button type="button" class="text-link" data-episode-hide="'+r.id+'">Ẩn tập</button>':'')+'</div></div>').join(''):'<p class="hint">Chưa có tập. Mỗi tập được lưu độc lập, không thay các tập trước.</p>'}
function edit(row=null){current=row;form.reset();for(const k of ['label','number','episode_order','title','url','description','cover_url'])form.elements[k].value=row?.[k]??(k==='label'?(rows.at(-1)?.label||'Tập'):k==='number'?(rows.at(-1)?.number||0)+1:k==='episode_order'?Math.max(0,...rows.map(e=>e.episode_order))+1:'');form.elements.inherit_cover.checked=row?.inherit_cover??true;dirty=false;controls();status(row?'Đã mở bản nháp. Lưu nháp không thay bản công khai cho đến khi đăng lại.':'Nhập link của tập mới, chọn bìa chung hoặc bìa riêng. Các tập cũ được giữ nguyên.')}
async function load(){const token=++sequence;if(!resource||preview){rows=[];live=[];render();edit();return}busy=true;controls();try{const data=await Promise.all([window.HVTVideoSeries.list(resource.id,true),window.HVTVideoSeries.list(resource.id)]);if(token!==sequence)return;[rows,live]=data;render();if(!dirty)edit(rows.find(r=>r.id===current?.id)||null)}catch(e){status('Chưa tải được các tập. Chạy upgrade-auto-rich-video.sql. '+e.message,true)}finally{if(token===sequence){busy=false;controls()}}}
async function save(publish){if(!resource||preview||busy||!form.reportValidity())return;const f=new FormData(form),url=f.get('url').trim(),coverURL=f.get('cover_url').trim();if(!c.https(url)||(coverURL&&!c.https(coverURL))){status('Link video và ảnh bìa phải là HTTPS.',true);return}busy=true;controls();try{let path=current?.cover_path||null;if(coverURL!==(current?.cover_url||''))path=null;const file=form.elements.cover_file.files[0];if(file)path=await c.upload('covers',await c.imageFile(file),'jpg');current=await rpc('save_video_episode',{p_id:current?.id||crypto.randomUUID(),p_resource_id:resource.id,p_expected_version:current?.version||0,p_data:{label:f.get('label'),number:Number(f.get('number')),episode_order:Number(f.get('episode_order')),title:f.get('title').trim(),url,description:f.get('description').trim(),inherit_cover:f.has('inherit_cover'),cover_path:path,cover_url:coverURL||null}});dirty=false;form.elements.cover_file.value='';if(publish)await rpc('publish_video_episode',{p_id:current.id,p_expected_version:current.version});await load();status(publish?'Đã công khai phần này. Các phần khác vẫn được giữ nguyên.':'Đã lưu nháp phần này. Các phần khác vẫn được giữ nguyên.')}catch(e){status(e.message,true)}finally{busy=false;controls()}}
form.addEventListener('input',()=>{dirty=true;controls()});form.elements.inherit_cover.onchange=controls;form.onsubmit=e=>{e.preventDefault();save(true)};$('#episodeSave').onclick=()=>save(false);$('#episodeNew').onclick=()=>{if(canLeave())edit()};$('#episodeReload').onclick=()=>{if(canLeave()){dirty=false;load()}};
$('#episodeList').onclick=async e=>{const editButton=e.target.closest('[data-episode-edit]'),hide=e.target.closest('[data-episode-hide]');if(busy||!canLeave())return;if(editButton)edit(rows.find(r=>r.id===editButton.dataset.episodeEdit));if(hide&&!preview){busy=true;controls();try{await c.api('/rest/v1/video_episodes?id=eq.'+hide.dataset.episodeHide,{method:'DELETE'});dirty=false;await load();status('Đã ẩn tập. Bản nháp vẫn còn để đăng lại.')}catch(error){status(error.message,true)}finally{busy=false;controls()}}};
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
window.HVTVideoAdmin={canLeave,attach(item,isPreview=false){const changed=resource?.id!==item?.id;resource=item;preview=isPreview;$('#episodeWorkspace').hidden=false;$('#episodeParent').textContent=item?.title||'Bộ video mới — lưu thông tin chung trước';if(changed){sequence++;rows=[];live=[];edit();render()}load()},detach(){sequence++;resource=null;rows=[];live=[];current=null;dirty=false;$('#episodeWorkspace').hidden=true},setBusy(value){busy=value;controls()}};
})();
